// Expo config plugin: sign Android release builds with the Play upload key.
//
// `expo prebuild` regenerates android/app/build.gradle from the Expo template,
// whose release build type is signed with the public debug keystore. Google Play
// rejects such bundles, and a debug-signed release is the kind of silent failure
// this app must not have. This plugin rewrites the generated file so that:
//
//   - on EAS Build, the release is left to EAS, which signs it with the upload
//     key it stores once it has written credentials.json to the build directory;
//   - otherwise a release signing config reads the upload key from, in order,
//     ANDROID_UPLOAD_* environment variables (CI) or
//     apps/mobile/credentials/android/keystore.properties (a developer's Mac);
//   - the release build type uses that config;
//   - any release task fails early, with the next step named, when no key is
//     configured, instead of falling back to the debug key.
//
// The key lives outside android/ on purpose: `expo prebuild --clean` deletes the
// whole native folder, and losing the upload key is a support ticket with Google.
//
// See apps/mobile/RELEASING.md.

const { withAppBuildGradle } = require('expo/config-plugins');

const PLUGIN = 'plugins/withAndroidReleaseSigning.js';
const HEADER_BEGIN = '// >>> speak-for-me release signing (generated by ' + PLUGIN + ', do not edit by hand)';
const HEADER_END = '// <<< speak-for-me release signing';
const SIGNING_BEGIN = '        // >>> speak-for-me release signing config';
const SIGNING_END = '        // <<< speak-for-me release signing config';

const HEADER_BLOCK = `${HEADER_BEGIN}
def speakForMeUploadKey = { ->
    def env = System.getenv()
    if (env['EAS_BUILD_WORKINGDIR']) {
        // EAS applies eas-build-inject-android-credentials.gradle, which signs the
        // release from this file. No file means EAS has no key: fail below.
        def easCredentials = new File(env['EAS_BUILD_WORKINGDIR'], 'credentials.json')
        if (!easCredentials.isFile()) {
            return null
        }
        return [managedByEas: true, source: easCredentials.absolutePath]
    }
    if (env['ANDROID_UPLOAD_STORE_FILE']) {
        return [
            storeFile: env['ANDROID_UPLOAD_STORE_FILE'],
            storePassword: env['ANDROID_UPLOAD_STORE_PASSWORD'],
            keyAlias: env['ANDROID_UPLOAD_KEY_ALIAS'],
            keyPassword: env['ANDROID_UPLOAD_KEY_PASSWORD'],
            baseDir: rootProject.projectDir.parentFile,
            source: 'ANDROID_UPLOAD_* environment variables',
        ]
    }
    def credentialsDir = new File(rootProject.projectDir.parentFile, 'credentials/android')
    def propertiesFile = new File(credentialsDir, 'keystore.properties')
    if (!propertiesFile.isFile()) {
        return null
    }
    def properties = new Properties()
    propertiesFile.withInputStream { properties.load(it) }
    return [
        storeFile: properties.getProperty('storeFile'),
        storePassword: properties.getProperty('storePassword'),
        keyAlias: properties.getProperty('keyAlias'),
        keyPassword: properties.getProperty('keyPassword'),
        baseDir: credentialsDir,
        source: propertiesFile.absolutePath,
    ]
}()

if (speakForMeUploadKey && !speakForMeUploadKey.managedByEas) {
    ['storeFile', 'storePassword', 'keyAlias', 'keyPassword'].each { key ->
        if (!speakForMeUploadKey[key]) {
            throw new GradleException("Speak For Me release signing: '\${key}' is missing from \${speakForMeUploadKey.source}. See apps/mobile/RELEASING.md.")
        }
    }
    def keystore = new File(speakForMeUploadKey.storeFile)
    if (!keystore.isAbsolute()) {
        keystore = new File(speakForMeUploadKey.baseDir, speakForMeUploadKey.storeFile)
    }
    if (!keystore.isFile()) {
        throw new GradleException("Speak For Me release signing: keystore not found at \${keystore.absolutePath} (configured in \${speakForMeUploadKey.source}). Run 'pnpm mobile release:setup' or fix the path. See apps/mobile/RELEASING.md.")
    }
    speakForMeUploadKey.resolvedStoreFile = keystore
}

gradle.taskGraph.whenReady { graph ->
    def wantsRelease = graph.allTasks.any { task ->
        task.project == project && task.name ==~ /(assemble|bundle|package|install)Release/
    }
    if (wantsRelease && !speakForMeUploadKey) {
        throw new GradleException(
            'Speak For Me release signing: no upload key is configured, so this release build would be signed ' +
            'with the public debug key and Google Play would reject it.\\n' +
            "  Next step: on EAS Build, run 'eas credentials -p android' to give the project a keystore; " +
            "locally, run 'pnpm mobile release:setup' to create credentials/android/keystore.properties, " +
            'or export ANDROID_UPLOAD_STORE_FILE, ANDROID_UPLOAD_STORE_PASSWORD, ANDROID_UPLOAD_KEY_ALIAS ' +
            'and ANDROID_UPLOAD_KEY_PASSWORD. See apps/mobile/RELEASING.md.'
        )
    }
}
${HEADER_END}`;

const SIGNING_BLOCK = `${SIGNING_BEGIN}
        release {
            if (speakForMeUploadKey && !speakForMeUploadKey.managedByEas) {
                storeFile speakForMeUploadKey.resolvedStoreFile
                storePassword speakForMeUploadKey.storePassword
                keyAlias speakForMeUploadKey.keyAlias
                keyPassword speakForMeUploadKey.keyPassword
            }
        }
${SIGNING_END}`;

const TEMPLATE_CAUTION = [
  '            // Caution! In production, you need to generate your own keystore file.',
  '            // see https://reactnative.dev/docs/signed-apk-android.',
  '            signingConfig signingConfigs.debug',
].join('\n');
const RELEASE_SIGNING_LINE = [
  '            // Signed with the Play upload key; see plugins/withAndroidReleaseSigning.js.',
  '            signingConfig signingConfigs.release',
].join('\n');

function fail(reason) {
  return new Error(
    `${PLUGIN}: ${reason} The Expo template for android/app/build.gradle has changed; ` +
      'update the plugin before releasing, otherwise release builds would fall back to the debug key.'
  );
}

/** Removes a previously generated block so an updated plugin can re-insert it. */
function stripBlock(contents, begin, end) {
  const start = contents.indexOf(begin);
  if (start === -1) return contents;
  const stop = contents.indexOf(end, start);
  if (stop === -1) throw fail(`found the marker "${begin}" without its closing marker.`);
  const after = stop + end.length;
  // Also drop the newline(s) the block was inserted with.
  const trailing = contents.slice(after).match(/^\n+/);
  return contents.slice(0, start) + contents.slice(after + (trailing ? trailing[0].length : 0));
}

/** Pure transform of android/app/build.gradle contents. Idempotent. */
function addReleaseSigning(contents) {
  let out = stripBlock(contents, HEADER_BEGIN, HEADER_END);
  out = stripBlock(out, SIGNING_BEGIN, SIGNING_END);

  // 1. Key lookup and release guard, just before the android {} block.
  const androidBlock = /^android \{$/m;
  if (!androidBlock.test(out)) throw fail('could not find the "android {" block.');
  out = out.replace(androidBlock, `${HEADER_BLOCK}\n\nandroid {`);

  // 2. A release signing config, after the template's debug one.
  const signingConfigsStart = out.indexOf('    signingConfigs {');
  if (signingConfigsStart === -1) throw fail('could not find the "signingConfigs {" block.');
  const debugStart = out.indexOf('        debug {', signingConfigsStart);
  if (debugStart === -1) throw fail('could not find the debug signing config.');
  const debugEnd = out.indexOf('\n        }\n', debugStart);
  if (debugEnd === -1) throw fail('could not find the end of the debug signing config.');
  const insertAt = debugEnd + '\n        }\n'.length;
  out = out.slice(0, insertAt) + SIGNING_BLOCK + '\n' + out.slice(insertAt);

  // 3. Point the release build type at it.
  const buildTypesStart = out.indexOf('    buildTypes {');
  if (buildTypesStart === -1) throw fail('could not find the "buildTypes {" block.');
  const releaseStart = out.indexOf('        release {', buildTypesStart);
  if (releaseStart === -1) throw fail('could not find the release build type.');
  const releaseEnd = out.indexOf('\n        }\n', releaseStart);
  if (releaseEnd === -1) throw fail('could not find the end of the release build type.');
  const releaseBody = out.slice(releaseStart, releaseEnd);
  if (!releaseBody.includes('signingConfig signingConfigs.release')) {
    const replaced = releaseBody.includes(TEMPLATE_CAUTION)
      ? releaseBody.replace(TEMPLATE_CAUTION, RELEASE_SIGNING_LINE)
      : releaseBody.includes('            signingConfig signingConfigs.debug')
        ? releaseBody.replace('            signingConfig signingConfigs.debug', RELEASE_SIGNING_LINE)
        : null;
    if (replaced === null) throw fail('the release build type does not use signingConfigs.debug as expected.');
    out = out.slice(0, releaseStart) + replaced + out.slice(releaseEnd);
  }

  return out;
}

/** @type {import('expo/config-plugins').ConfigPlugin} */
function withAndroidReleaseSigning(config) {
  return withAppBuildGradle(config, (config) => {
    if (config.modResults.language !== 'groovy') {
      throw fail(`expected a Groovy build.gradle but found "${config.modResults.language}".`);
    }
    config.modResults.contents = addReleaseSigning(config.modResults.contents);
    return config;
  });
}

module.exports = withAndroidReleaseSigning;
module.exports.addReleaseSigning = addReleaseSigning;
